package com.mavric.health.persistence.sqlserver;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real adapter/templates with executor/manager doubles; no portal link, revocation or engine evidence. */
public class SqlServerPortalAppointmentStoreTest {
 public static final String ACTOR="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",APPOINTMENT="cc000000-0000-4000-8000-000000000001",PATIENT="dd000000-0000-4000-8000-000000000001",OTHER="ee000000-0000-4000-8000-000000000001",DATE="2026-11-05T00:00:00.123456Z";
 public static Map<String,Object> row(){var r=new LinkedHashMap<String,Object>();r.put("id",APPOINTMENT);r.put("branchId",OTHER);r.put("professionalId",ACTOR);r.put("specialtyCode","H_FAMILY");r.put("startsAt",DATE);r.put("endsAt",java.time.Instant.parse(DATE).plusSeconds(1800).toString());r.put("status","RESERVED");r.put("service","Synthetic \u4e2d\ud83e\uddb7");r.put("revision",1);return r;}
 public static class Fixture {
  public final SqlServerExecutor executor=mock(SqlServerExecutor.class);public final ModelTransactionManager manager=new ModelTransactionManager();public final SqlServerPortalAppointmentStore store=new SqlServerPortalAppointmentStore(executor,manager);public final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/portal/appointments");public Actor actor;public List<Map<String,Object>> rows=new ArrayList<>();public final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();public final List<List<Object>> args=new ArrayList<>();public final List<SqlServerContext> contexts=new ArrayList<>();
  public Fixture(){actor("PAC");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.PORTAL_APPOINTMENTS,inv.getArgument(0));var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ACTOR,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());contexts.add(c);args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));manager.events.add("sp:PORTAL_APPOINTMENTS");return results.isEmpty()?new SqlServerExecutor.Result(List.of(rows),List.of()):results.removeFirst();});}
  public void actor(String role){actor=new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of(role),"a".repeat(64));request.setAttribute("health.actor",actor);request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("PORTAL")));request.setAttribute("health.requestId",OTHER);}
 }
 final Fixture f=new Fixture();
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable r){var e=assertThrows(ApiException.class,r::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}
 @Test void oneSpOneArgumentRequestContextAndExactImmutableNineFieldProjection(){var row=row();row.put("passwordHash","private-canary");row.put("tenantId",OTHER);row.put("note","private-canary");f.rows.add(row);TraceContext.REQUEST.set(new MockHttpServletRequest());var output=f.store.appointments(f.request,PATIENT);assertEquals(9,output.getFirst().size());assertEquals(Set.of("id","branchId","professionalId","specialtyCode","startsAt","endsAt","status","service","revision"),output.getFirst().keySet());assertFalse(output.toString().contains("private-canary"));assertFalse(output.getFirst().containsKey("note"));assertFalse(output.getFirst().containsKey("tenantId"));assertEquals(List.of(PATIENT),f.args.getFirst());assertEquals(List.of("PAC"),f.contexts.getFirst().roles());assertEquals(List.of("begin:0","sp:PORTAL_APPOINTMENTS","commit"),f.manager.events);assertThrows(UnsupportedOperationException.class,output::clear);assertThrows(UnsupportedOperationException.class,output.getFirst()::clear);}
 @Test void emptyAndTwoHundredRowsPreserveSpOrderAndUnicodeService(){assertTrue(f.store.appointments(f.request,PATIENT).isEmpty());for(int i=0;i<200;i++){var row=row();row.put("id",UUID.nameUUIDFromBytes(("synthetic-"+i).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString());row.put("service","\u4e2d".repeat(160));row.put("startsAt",java.time.Instant.parse(DATE).minusSeconds(i*3600L).toString());row.put("endsAt",java.time.Instant.parse(DATE).minusSeconds(i*3600L).plusSeconds(1800).toString());f.rows.add(row);}var output=f.store.appointments(f.request,PATIENT);assertEquals(200,output.size());assertEquals(f.rows.getFirst(),output.getFirst());assertEquals(f.rows.getLast(),output.getLast());f.rows.add(row());safe(()->f.store.appointments(f.request,PATIENT));}
 @Test void allDeclaredStatesPreservedWithoutFilteringOrTransitions(){for(String state:List.of("REQUESTED","RESERVED","CONFIRMED","WAITING","CALLED","IN_CARE","COMPLETED","CANCELLED","WITHDRAWN")){var row=row();row.put("status",state);f.rows.clear();f.rows.add(row);assertEquals(state,f.store.appointments(f.request,PATIENT).getFirst().get("status"));}}
 @Test void rolesAndModuleRevalidatedButNoStatusOrCoreGateAdded(){for(String role:List.of("PAC","RES")){f.actor(role);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of("PORTAL")));assertTrue(f.store.appointments(f.request,PATIENT).isEmpty());}for(String role:List.of("ADM","REC","PRO","ASI","AUD","SAD","SOP")){f.actor(role);assertEquals(403,assertThrows(ApiException.class,()->f.store.appointments(f.request,PATIENT)).status);}f.actor("PAC");f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("CORE")));assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->f.store.appointments(f.request,PATIENT)).code);assertEquals(2,f.args.size());}
 @Test void nullRequestForgedContextUuidAndTokenFailBeforeExecutor(){safe(()->f.store.appointments(null,PATIENT));f.request.setAttribute("health.tenant","bad");safe(()->f.store.appointments(f.request,PATIENT));f.actor("PAC");f.request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->f.store.appointments(f.request,PATIENT)).status);f.actor("PAC");f.request.setAttribute("health.actor",new Actor("bad","Synthetic","synthetic@example.test",TENANT,List.of("PAC"),"a".repeat(64)));safe(()->f.store.appointments(f.request,PATIENT));f.request.setAttribute("health.actor",new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of("PAC"),"bad"));safe(()->f.store.appointments(f.request,PATIENT));f.actor("PAC");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("PORTAL")));assertEquals(403,assertThrows(ApiException.class,()->f.store.appointments(f.request,PATIENT)).status);verifyNoInteractions(f.executor);}
 @Test void patientUuidCanonicalAndNoQueryForInvalidIds(){for(String id:Arrays.asList(null,"bad",PATIENT.toUpperCase()))assertEquals(400,assertThrows(ApiException.class,()->f.store.appointments(f.request,id)).status);verifyNoInteractions(f.executor);}
 @Test void absentMultipleResultsetsAndWrongCardinalityAreDatabaseErrors(){for(var result:List.of(new SqlServerExecutor.Result(List.of(),List.of()),new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()),new SqlServerExecutor.Result(List.of(Collections.nCopies(201,row())),List.of()))){f.results.add(result);safe(()->f.store.appointments(f.request,PATIENT));assertEquals("rollback",f.manager.events.getLast());}}
 @Test void allFieldsRequiredNonnullableTypesDomainAndTimestampsChecked(){for(String key:row().keySet()){var bad=row();bad.remove(key);f.results.add(new SqlServerExecutor.Result(List.of(List.of(bad)),List.of()));safe(()->f.store.appointments(f.request,PATIENT));bad=row();bad.put(key,null);f.results.add(new SqlServerExecutor.Result(List.of(List.of(bad)),List.of()));safe(()->f.store.appointments(f.request,PATIENT));}for(var entry:List.of(Map.entry("id","bad"),Map.entry("branchId","bad"),Map.entry("professionalId","bad"),Map.entry("revision",1L),Map.entry("revision",0),Map.entry("status","bad"),Map.entry("status","reserved"),Map.entry("service",1),Map.entry("service"," "),Map.entry("service","x".repeat(161)),Map.entry("specialtyCode",1),Map.entry("specialtyCode","bad code"),Map.entry("specialtyCode","x".repeat(101)),Map.entry("startsAt","2026-11-05T00:00:00.123456789Z"),Map.entry("startsAt","2026-11-05T00:00:00+00:00"),Map.entry("endsAt",DATE),Map.entry("endsAt",java.time.Instant.parse(DATE).minusSeconds(1).toString()),Map.entry("endsAt","+10000-01-01T00:00:00Z"),Map.entry("startsAt","0000-01-01T00:00:00Z"))){var bad=row();bad.put(entry.getKey(),entry.getValue());f.results.add(new SqlServerExecutor.Result(List.of(List.of(bad)),List.of()));safe(()->f.store.appointments(f.request,PATIENT));assertEquals("rollback",f.manager.events.getLast());}}
 @Test void moduleLinkAndPermissionSpErrorsAreMappedWithoutRetryOrFakeEmpty(){for(int vendor:List.of(51001,51002,51003)){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,vendor))).when(f.executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->f.store.appointments(f.request,PATIENT));assertEquals(vendor==51001?403:vendor==51002?404:409,error.status);assertNull(error.getCause());assertFalse(error.toString().contains("canary"));}verify(f.executor,times(3)).execute(eq(SqlServerProcedure.PORTAL_APPOINTMENTS),any(),eq(PATIENT));}
 @Test void requiredJoinMappingRollbackAndCommitFailureNeverFallBack(){assertThrows(RuntimeException.class,()->f.manager.outer(()->{f.store.appointments(f.request,PATIENT);assertFalse(f.manager.events.contains("commit"));throw new RuntimeException("cancel");}));assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));assertEquals("rollback",f.manager.events.getLast());f.manager.failCommit=true;safe(()->f.store.appointments(f.request,PATIENT));assertEquals(2,f.args.size());assertEquals("SqlServerPortalAppointmentStore[redacted]",f.store.toString());}
}
